package pov

type Tree struct {
	value    string
	children []*Tree
}

// New creates and returns a new Tree with the given root value and children.
func New(value string, children ...*Tree) *Tree {
	return &Tree{value: value, children: children}
}

// Value returns the value at the root of a tree.
func (tr *Tree) Value() string {
	return tr.value
}

// Children returns a slice containing the children of a tree.
// There is no need to sort the elements in the result slice,
// they can be in any order.
func (tr *Tree) Children() []*Tree {
	return tr.children
}

// String describes a tree in a compact S-expression format.
// This helps to make test outputs more readable.
// Feel free to adapt this method as you see fit.
func (tr *Tree) String() string {
	if tr == nil {
		return "nil"
	}
	result := tr.Value()
	if len(tr.Children()) == 0 {
		return result
	}
	for _, ch := range tr.Children() {
		result += " " + ch.String()
	}
	return "(" + result + ")"
}

// POV problem-specific functions

// FromPov returns the pov from the node specified in the argument.
// It returns nil if the tree does not contain a node with that value.
func (tr *Tree) FromPov(from string) *Tree {
	return reorient(tr, from, nil)
}

// reorient rebuilds the tree rooted at the node whose value is `from`.
// `exclude` is the node we came from in the original orientation, so it
// is never visited twice; when the target is found, the excluded node is
// attached as a child of the new root.
func reorient(tr *Tree, from string, exclude *Tree) *Tree {
	if tr == nil {
		return nil
	}
	if tr.value == from {
		children := make([]*Tree, 0, len(tr.children)+1)
		for _, ch := range tr.children {
			children = append(children, reorient(ch, from, tr))
		}
		if exclude != nil {
			children = append(children, reorient(exclude, from, tr))
		}
		return &Tree{value: tr.value, children: children}
	}
	children := make([]*Tree, 0, len(tr.children))
	for _, ch := range tr.children {
		if ch == exclude {
			continue
		}
		children = append(children, reorient(ch, from, tr))
	}
	return &Tree{value: tr.value, children: children}
}

// PathTo returns the shortest path between two nodes in the tree.
// It returns nil if either node does not exist.
func (tr *Tree) PathTo(from, to string) []string {
	rooted := tr.FromPov(from)
	if rooted == nil {
		return nil
	}
	return pathFrom(rooted, to)
}

// pathFrom walks the tree (already rooted at `from`) and returns the path
// from the root to the node whose value is `to`, or nil if not found.
func pathFrom(tr *Tree, to string) []string {
	if tr.value == to {
		return []string{tr.value}
	}
	for _, ch := range tr.children {
		if p := pathFrom(ch, to); p != nil {
			return append([]string{tr.value}, p...)
		}
	}
	return nil
}

